#!/bin/bash
# Prueba de solo lectura de evaluar-imagenes-ocp.yml contra el SNO. Enciende el SNO solo si está apagado y lo deja como estaba.
D=$HOME/openshift/sno; KC=$D/instalar/auth/kubeconfig; OC=$D/bin/oc
E0=$(sudo virsh domstate sno 2>&1 | head -1); echo "SNO_ESTADO_INICIAL: $E0"
if [ "$E0" != "running" ]; then sudo virsh start sno >/dev/null 2>&1; echo "SNO encendido por la prueba"; fi
for i in $(seq 1 90); do $OC --kubeconfig $KC get --raw /readyz >/dev/null 2>&1 && break; sleep 10; done
echo "API: $($OC --kubeconfig $KC get --raw /readyz 2>&1 | head -1) tras $((i*10))s"
for i in $(seq 1 60); do n=$($OC --kubeconfig $KC get co --no-headers 2>/dev/null | awk '$3!="True"||$5=="True"' | wc -l); [ "$n" = 0 ] && break; sleep 15; done; echo "operadores no listos: $n"
W=/tmp/imgocp-$$; mkdir -p $W && cd $W
echo "" | base64 -d | tar xzf -
python3 -m venv $W/venv >/dev/null && $W/venv/bin/pip install -q "ansible>=8,<9" kubernetes 2>&1 | grep -v -i "warning\|upgrade\|notice" | tail -3
export PATH=$W/venv/bin:$D/bin:$PATH ANSIBLE_LOCALHOST_WARNING=False ANSIBLE_COLLECTIONS_PATH=$W/none
ansible --version | head -1; ansible-galaxy collection list 2>/dev/null | grep -E "^kubernetes.core|^community.general"
cd imagenes-ocp; ansible-playbook --syntax-check evaluar-imagenes-ocp.yml 2>&1 | grep -v WARNING | tail -6
T0=$(date +%s)
ansible-playbook evaluar-imagenes-ocp.yml -e ocp_kubeconfig=$KC -e reporte_dir=$W/out -e revisiones_a_conservar=1 -e dias_antiguedad_revision=2 -e dias_antiguedad_imagestream=5 -e nodos_modo=api > $W/run.log 2>&1; echo "RC $?"
grep -v -i -E "token|password|secret|bearer|certificate-authority-data|client-key" $W/run.log | grep -E '^(TASK|fatal|failed|PLAY RECAP|localhost)|ERROR|"(Clúster|Registro|Espacio|Caché|Bloque|Aviso|Reporte|No disponible|msg)|skipping' | cut -c1-300
echo "DURACION $(($(date +%s)-T0))s"; ls -la $W/out 2>&1 | awk '{print $5, $9}'
echo "== estados"; python3 -c "
import json,glob,collections;e=json.load(open(glob.glob('$W/out/*.json')[0]))
print(collections.Counter(f['estado'] for f in e['imagenes']).most_common())
print([(b['id'],b['cantidad'],b['espacio']) for b in e['bloques']])
for b in e['bloques']: print(b['id'], [(g['grupo'],g['cantidad'],g['espacio']) for g in b['por_grupo']][:12])
for n in e['nodos']: print(n['nodo'], n['fuente'], n['imagenes'], n['tamano'], n['no_usado'], n['fs_total'], n['fs_usado'])
print(e['avisos'])
" 2>&1 | cut -c1-1500
echo "debug ns restantes: $($OC --kubeconfig $KC get ns --no-headers 2>/dev/null | grep -c openshift-debug)"
cd /; rm -rf $W
if [ "$E0" != "running" ]; then sudo virsh shutdown sno >/dev/null 2>&1; for i in $(seq 1 40); do [ "$(sudo virsh domstate sno)" = "shut off" ] && break; sleep 15; done; fi
echo "SNO_ESTADO_FINAL: $(sudo virsh domstate sno | head -1)"
